id($product['nid_material_products']);                  ?>               <tr>                  <td><a href="<?php echo base_url().$sec['ccode'].'/'.$cat['ccode'].'/'.$product['ccode']; ?>" target="_blank"><img src="<?php echo $fr_img.'upload/images_product/resize_images/'.$product['cimage_resize']?>" style="width: 80px;" /></a></td>                  <td><?php echo Fview_text($product['cproducts']) ?>				  <?php if($data['niscolor']==1) { ?>				   <br><span style="color:red;">(Màu: <?php echo $color['cname']; ?>)</span>				   <?php } ?>				   </td>                  <td style="text-align:right"><?php echo Fview_text($data['nquantity']) ?></td>                  <td style="text-align:right">                     <?php 							echo Fview_text(number_format($price)).' '.$lbl_vnd;							if($product['fprice_sale'] < $product['fprice'] && ($product['ncheck'] == 1 || $product['cflash'] == 1)) 									echo '<br><del style="color: red;">'.Fview_text(number_format($product['fprice'])).' '.$lbl_vnd.'</del>';                        ?>                  </td>                  <td style="text-align:right">                     <?php                         	echo Fview_text(number_format($data['nquantity']*$price)).' '.$lbl_vnd;                        ?>                  </td>               </tr>               <?php endforeach; ?>               <tr>                  <td colspan="4" style="text-align:right"><b><?php echo "Tổng tiền (chưa giảm giá)" ?> : </b></td>                  <td style="text-align:right;color:red;"><b><?php echo Fview_text(number_format($total_no_sale)).' '.$lbl_vnd ?></b></td>               </tr>			   <tr>                  <td colspan="4" style="text-align:right"><b><?php echo "Giảm giá (khuyến mãi)" ?> : </b></td>                  <td style="text-align:right;color:red;"><b><?php if($total_sale!=0) echo Fview_text(number_format($total_sale)).' '.$lbl_vnd; else echo "0 VNĐ"; ?></b></td>               </tr>			   <?php /*			   <tr>    